-- Makler und Unternehmen aus dem HubSpot-Export übernehmen (19.10.2026).
-- Quelle: supabase/daten/hubspot-makler-2026-10-05.csv; der Datenblock unten wird mit supabase/daten/csv-zu-sql.mjs erzeugt.
-- Läuft nach `unternehmen_uebernahme` und lässt sich gefahrlos erneut ausführen.
--
-- Makler: gesucht über E-Mail, sonst Telefon, sonst vollen Namen (jeweils nur, wenn genau einer passt; ohne Papierkorb).
--   Vorhanden: nur leere Felder werden gefüllt. Ausnahme Priorität: die HubSpot-Klassifizierung gewinnt
--   (VIP und High Potential → A, B → B, C → C; sonst bleibt die Priorität).
--   Nicht vorhanden: neu angelegt, Kontakt-Frequenz „Monatlich“, Priorität aus der Klassifizierung (sonst leer).
--   Ohne E-Mail, Telefon und Namen wird eine Zeile übergangen; doppelte Zeilen (gleiche E-Mail bzw. Name) zählen einmal.
-- Unternehmen: nur mit Firmennamen, gesucht über den Firmenschlüssel. Vorhanden: nur Lücken füllen, sonst neu.
--   Ein Makler mit Unternehmen behält es; ohne bekommt er das aus HubSpot; ohne Firmennamen bleibt er ohne.
-- Zusätzliche E-Mail-Adressen gehen in die weiteren Kontakte des Unternehmens (ohne Unternehmen: an den Makler).

create or replace function pg_temp.unternehmen_schluessel(t text) returns text language sql immutable as $$
  select nullif(btrim(
    regexp_replace(
      regexp_replace(
        regexp_replace(
          regexp_replace(lower(normalize(coalesce(t, ''), NFKC)), '[.,;:()"''„“”‚‘’`´]', ' ', 'g'),
          '[-–—]', ' ', 'g'),
        '\s*([&+/])\s*', '\1', 'g'),
      '\s+', ' ', 'g')), '')
$$;

create or replace function pg_temp.unternehmen_domain(webseite text, email text) returns text language plpgsql immutable as $$
declare
  host text := substring(regexp_replace(regexp_replace(lower(btrim(coalesce(webseite, ''))), '^[a-z]+://', ''), '^www\.', '') from '^[^/?#:\s]*');
  d text := split_part(lower(btrim(coalesce(email, ''))), '@', 2);
begin
  if host like '%.%' then return host; end if;
  if d like '%.%' and d not in ('gmail.com', 'googlemail.com', 'gmx.de', 'gmx.net', 'gmx.at', 'web.de', 't-online.de', 'yahoo.com',
    'yahoo.de', 'outlook.com', 'outlook.de', 'hotmail.com', 'hotmail.de', 'live.com', 'live.de', 'icloud.com', 'me.com', 'freenet.de',
    'aol.com', 'posteo.de', 'mail.de', 'online.de', 'arcor.de', 'email.de', 'vodafone.de', '1und1.de') then return d; end if;
  return null;
end $$;

create or replace function pg_temp.telefon_schluessel(v text) returns text language sql immutable as $$
  select regexp_replace(regexp_replace(coalesce(v, ''), '\D', '', 'g'), '^(0049|49)0?', '0')
$$;

-- wie `telefonNormalisieren` in @gg/domain
create or replace function pg_temp.telefon(v text) returns text language sql immutable as $$
  select nullif(regexp_replace(regexp_replace(regexp_replace(btrim(coalesce(v, '')), '^0049', '+49'), '[()]', '', 'g'), '\s{2,}', ' ', 'g'), '')
$$;

create or replace function pg_temp.kontakte_vereinen(listen jsonb, haupt jsonb) returns jsonb language plpgsql immutable as $$
declare
  art text; liste jsonb; e jsonb; t text; s text; gesehen text[]; aus jsonb := '{}'; werte jsonb;
begin
  foreach art in array array['namen', 'telefonnummern', 'emails'] loop
    gesehen := case art
      when 'telefonnummern' then array(select pg_temp.telefon_schluessel(x) from jsonb_array_elements(coalesce(haupt, '[]')) h,
        lateral unnest(array[h->>'tel', h->>'mobil', h->>'festnetz']) x where coalesce(x, '') <> '')
      when 'namen' then array(select lower(h->>'name') from jsonb_array_elements(coalesce(haupt, '[]')) h where coalesce(h->>'name', '') <> '')
      else array(select lower(h->>'email') from jsonb_array_elements(coalesce(haupt, '[]')) h where coalesce(h->>'email', '') <> '')
    end;
    werte := '[]';
    for liste in select l from jsonb_array_elements(coalesce(listen, '[]')) l loop
      if jsonb_typeof(liste->art) is distinct from 'array' then continue; end if;
      for e in select x from jsonb_array_elements(liste->art) x loop
        t := case when jsonb_typeof(e) = 'string' then btrim(e #>> '{}') else '' end;
        s := case when t = '' then '' when art = 'telefonnummern' then pg_temp.telefon_schluessel(t) else lower(t) end;
        if s = '' or s = any(gesehen) then continue; end if;
        gesehen := gesehen || s;
        werte := werte || to_jsonb(t);
      end loop;
    end loop;
    aus := aus || jsonb_build_object(art, werte);
  end loop;
  if jsonb_array_length(aus->'namen') + jsonb_array_length(aus->'telefonnummern') + jsonb_array_length(aus->'emails') = 0 then return null; end if;
  return aus;
end $$;

drop table if exists pg_temp.hubspot_roh, pg_temp.hs, pg_temp.hs_makler, pg_temp.hs_firma;

create temp table hubspot_roh (
  zeile int, vorname text, nachname text, anrede text, email text, weitere_emails text, telefon text, mobil text, du_sie text,
  letzte_kontaktaufnahme text, klassifizierung text, jobbezeichnung text, beruf text, stellung text, zustaendig text, hinweis text,
  mailing_status text, mails_abgemeldet text, rechtsgrundlage text, quelle text, unternehmensname text, unternehmen text,
  webseite text, website_url text, strasse text, plz text, ort text, fax text
);

-- DATEN ANFANG
-- DATEN ENDE

-- Aufbereiten
create temp table hs as
select r.zeile,
  nullif(btrim(r.vorname), '') as vorname,
  nullif(btrim(r.nachname), '') as nachname,
  nullif(concat_ws(' ', nullif(btrim(r.vorname), ''), nullif(btrim(r.nachname), '')), '') as voll,
  nullif(btrim(r.email), '') as email,
  lower(nullif(btrim(r.email), '')) as email_klein,
  array(select btrim(x) from unnest(string_to_array(coalesce(r.weitere_emails, ''), ';')) x where btrim(x) <> '') as weitere_emails,
  pg_temp.telefon(r.telefon) as tel,
  pg_temp.telefon(r.mobil) as mobil,
  case btrim(r.du_sie) when 'per Du' then 'du' when 'per Sie' then 'sie' end as anrede_form,
  nullif(btrim(r.letzte_kontaktaufnahme), '')::date as letzter_kontakt,
  case btrim(r.klassifizierung) when 'VIP' then 'A' when 'High Potential' then 'A' when 'B' then 'B' when 'C' then 'C' end as prio,
  nullif(btrim(r.anrede), '') as anrede,
  coalesce(nullif(btrim(r.jobbezeichnung), ''), nullif(btrim(r.beruf), '')) as position,
  nullif(btrim(r.stellung), '') as stellung,
  nullif(btrim(r.zustaendig), '') as zustaendig,
  nullif(btrim(r.hinweis), '') as hinweis,
  nullif(btrim(r.mailing_status), '') as mailing_status,
  coalesce(lower(btrim(r.mails_abgemeldet)) = 'true', false) as mails_abgemeldet,
  nullif(btrim(r.rechtsgrundlage), '') as rechtsgrundlage,
  nullif(btrim(r.quelle), '') as quelle,
  btrim(regexp_replace(coalesce(nullif(btrim(r.unternehmensname), ''), nullif(btrim(r.unternehmen), '')), '\s+', ' ', 'g')) as firma,
  pg_temp.unternehmen_schluessel(coalesce(nullif(btrim(r.unternehmensname), ''), nullif(btrim(r.unternehmen), ''))) as schluessel,
  coalesce(nullif(btrim(r.webseite), ''), nullif(btrim(r.website_url), '')) as webseite,
  nullif(btrim(r.strasse), '') as strasse,
  nullif(btrim(r.plz), '') as plz,
  nullif(btrim(r.ort), '') as ort,
  nullif(btrim(r.fax), '') as fax
from hubspot_roh r;

-- Doppelte Zeilen: je E-Mail bzw. (ohne E-Mail) je Name nur die erste; ohne E-Mail, Telefon und Namen keine
delete from hs where zeile in (
  select zeile from (select zeile, row_number() over (partition by email_klein order by zeile) n from hs where email_klein is not null) x where n > 1
  union all
  select zeile from (select zeile, row_number() over (partition by lower(voll) order by zeile) n from hs where email_klein is null and voll is not null) x where n > 1
  union all
  select zeile from hs where email_klein is null and voll is null and tel is null and mobil is null
);

-- Vorhandene Makler finden: E-Mail, sonst Telefon, sonst Name — jeweils nur eindeutig
create temp table hs_makler as
with bestand as (
  select id, lower(btrim(email)) as email_klein, lower(nullif(concat_ws(' ', vorname, name), '')) as voll,
    array_remove(array[nullif(pg_temp.telefon_schluessel(tel), ''), nullif(pg_temp.telefon_schluessel(mobil), ''), nullif(pg_temp.telefon_schluessel(festnetz), '')], null) as tels
  from fach.makler where deleted_at is null
),
treffer as (
  select h.zeile,
    coalesce(
      (select min(b.id) from bestand b where b.email_klein = h.email_klein having count(*) = 1),
      (select min(b.id) from bestand b where b.tels && array_remove(array[nullif(pg_temp.telefon_schluessel(h.tel), ''), nullif(pg_temp.telefon_schluessel(h.mobil), '')], null) having count(*) = 1),
      (select min(b.id) from bestand b where b.voll = lower(regexp_replace(h.voll, '\s+', ' ', 'g')) having count(*) = 1)
    ) as makler_id,
    exists (select 1 from bestand b where b.email_klein = h.email_klein
      or b.tels && array_remove(array[nullif(pg_temp.telefon_schluessel(h.tel), ''), nullif(pg_temp.telefon_schluessel(h.mobil), '')], null)
      or b.voll = lower(regexp_replace(h.voll, '\s+', ' ', 'g'))) as irgendwer
  from hs h
)
select t.zeile, t.makler_id, t.irgendwer,
  t.makler_id is not null and t.zeile = min(t.zeile) over (partition by t.makler_id) as erste
from treffer t;

-- Unternehmen: je Schlüssel einmal; Name = häufigste Schreibweise (bei Gleichstand nicht in Großbuchstaben, sonst die erste)
create temp table hs_firma as
select g.schluessel,
  (select f from (select h.firma f, count(*) n, min(h.zeile) o from hs h where h.schluessel = g.schluessel group by 1) s
   order by n desc, (f = upper(f)), o limit 1) as name,
  (select h.webseite from hs h where h.schluessel = g.schluessel and h.webseite is not null order by h.zeile limit 1) as webseite,
  (select d from (select pg_temp.unternehmen_domain(null, h.email) d, h.zeile from hs h where h.schluessel = g.schluessel) s
   where d is not null group by d order by count(*) desc, min(zeile) limit 1) as mail_domain,
  (select jsonb_build_object('strasse', h.strasse, 'plz', h.plz, 'ort', h.ort) from hs h
   where h.schluessel = g.schluessel and (h.strasse is not null or h.ort is not null) order by h.zeile limit 1) as anschrift,
  (select h.fax from hs h where h.schluessel = g.schluessel and h.fax is not null order by h.zeile limit 1) as fax,
  (select u.id from fach.unternehmen u where u.name_schluessel = g.schluessel and u.deleted_at is null order by u.created_at, u.id limit 1) as id
from (select distinct schluessel from hs where schluessel is not null) g;

-- Vorhandene Unternehmen: nur Lücken füllen
with ergaenzt as (
  select u.id,
    case when coalesce(btrim(u.webseite), '') = '' then coalesce(f.webseite, u.webseite) else u.webseite end as webseite,
    case when coalesce(btrim(u.domain), '') = '' then coalesce(pg_temp.unternehmen_domain(f.webseite, null), f.mail_domain, u.domain) else u.domain end as domain,
    case when x.adresse_leer and f.anschrift is not null then f.anschrift->>'strasse' else u.strasse end as strasse,
    case when x.adresse_leer and f.anschrift is not null then f.anschrift->>'plz' else u.plz end as plz,
    case when x.adresse_leer and f.anschrift is not null then f.anschrift->>'ort' else u.ort end as ort,
    case when coalesce(btrim(u.fax), '') = '' then coalesce(f.fax, u.fax) else u.fax end as fax
  from fach.unternehmen u
  join hs_firma f on f.id = u.id
  cross join lateral (select coalesce(btrim(u.strasse), '') = '' and coalesce(btrim(u.plz), '') = '' and coalesce(btrim(u.ort), '') = '' as adresse_leer) x
)
update fach.unternehmen u set
  webseite = e.webseite, domain = e.domain, strasse = e.strasse, plz = e.plz, ort = e.ort, fax = e.fax,
  version = u.version + 1, updated_at = now()
from ergaenzt e
where u.id = e.id
  and (u.webseite, u.domain, u.strasse, u.plz, u.ort, u.fax) is distinct from (e.webseite, e.domain, e.strasse, e.plz, e.ort, e.fax);

-- Neue Unternehmen
update hs_firma set id = gen_random_uuid()::text where id is null and name is not null;
select f.id, f.name, f.schluessel, f.webseite, coalesce(pg_temp.unternehmen_domain(f.webseite, null), f.mail_domain),
  f.anschrift->>'strasse', f.anschrift->>'plz', f.anschrift->>'ort', f.fax
from hs_firma f
where not exists (select 1 from fach.unternehmen u where u.id = f.id);

-- Vorhandene Makler: nur leere Felder füllen, Priorität aus HubSpot; Version nur, wenn sich etwas ändert
with neu as (
  select m.id,
    case when m.vorname is null and coalesce(btrim(m.name), '') = '' and h.nachname is not null then h.vorname else m.vorname end as vorname,
    case when coalesce(btrim(m.name), '') = '' and m.vorname is null then coalesce(h.nachname, h.vorname) else m.name end as name,
    coalesce(nullif(btrim(m.email), ''), h.email) as email,
    coalesce(nullif(btrim(m.tel), ''), h.tel, h.mobil) as tel,
    coalesce(nullif(btrim(m.mobil), ''), h.mobil) as mobil,
    coalesce(h.prio, m.prio) as prio,
    coalesce(m.last_contact, h.letzter_kontakt) as last_contact,
    case when h.anrede_form is not null and coalesce(m.persoenlich->>'anredeForm', '') = ''
      then coalesce(m.persoenlich, '{}') || jsonb_build_object('anredeForm', h.anrede_form) else m.persoenlich end as persoenlich,
    coalesce(nullif(btrim(m.anrede), ''), h.anrede) as anrede,
    coalesce(nullif(btrim(m.position), ''), h.position) as position,
    coalesce(nullif(btrim(m.stellung), ''), h.stellung) as stellung,
    coalesce(nullif(btrim(m.zustaendig), ''), h.zustaendig) as zustaendig,
    coalesce(nullif(btrim(m.hinweis), ''), h.hinweis) as hinweis,
    coalesce(nullif(btrim(m.mailing_status), ''), h.mailing_status) as mailing_status,
    m.mails_abgemeldet or h.mails_abgemeldet as mails_abgemeldet,
    coalesce(nullif(btrim(m.rechtsgrundlage), ''), h.rechtsgrundlage) as rechtsgrundlage,
    coalesce(nullif(btrim(m.quelle), ''), h.quelle) as quelle,
    coalesce(m.unternehmen_id, f.id) as unternehmen_id
  from hs_makler t
  join hs h on h.zeile = t.zeile
  join fach.makler m on m.id = t.makler_id
  left join hs_firma f on f.schluessel = h.schluessel
  where t.erste
)
update fach.makler m set
  vorname = n.vorname, name = n.name, email = n.email, tel = n.tel, mobil = n.mobil, prio = n.prio, last_contact = n.last_contact,
  persoenlich = n.persoenlich, anrede = n.anrede, position = n.position, stellung = n.stellung, zustaendig = n.zustaendig,
  hinweis = n.hinweis, mailing_status = n.mailing_status, mails_abgemeldet = n.mails_abgemeldet, rechtsgrundlage = n.rechtsgrundlage,
  quelle = n.quelle, unternehmen_id = n.unternehmen_id,
  version = m.version + 1, updated_at = now()
from neu n
where m.id = n.id
  and (m.vorname, m.name, m.email, m.tel, m.mobil, m.prio, m.last_contact, m.persoenlich, m.anrede, m.position, m.stellung, m.zustaendig,
       m.hinweis, m.mailing_status, m.mails_abgemeldet, m.rechtsgrundlage, m.quelle, m.unternehmen_id)
    is distinct from
      (n.vorname, n.name, n.email, n.tel, n.mobil, n.prio, n.last_contact, n.persoenlich, n.anrede, n.position, n.stellung, n.zustaendig,
       n.hinweis, n.mailing_status, n.mails_abgemeldet, n.rechtsgrundlage, n.quelle, n.unternehmen_id);

-- Neue Makler: nur, wenn niemand im Bestand dieselbe E-Mail, Telefonnummer oder denselben Namen hat
  stellung, zustaendig, hinweis, mailing_status, mails_abgemeldet, rechtsgrundlage, quelle, unternehmen_id, weitere_kontakte)
select gen_random_uuid()::text,
  case when h.nachname is not null then h.vorname end, coalesce(h.nachname, h.vorname),
  h.email, coalesce(h.tel, h.mobil), h.mobil, h.prio, 'Monatlich', h.letzter_kontakt,
  case when h.anrede_form is not null then jsonb_build_object('anredeForm', h.anrede_form) end,
  h.anrede, h.position, h.stellung, h.zustaendig, h.hinweis, h.mailing_status, h.mails_abgemeldet, h.rechtsgrundlage, h.quelle, f.id,
  case when f.id is null and cardinality(h.weitere_emails) > 0
    then jsonb_build_object('namen', '[]'::jsonb, 'telefonnummern', '[]'::jsonb, 'emails', to_jsonb(h.weitere_emails)) end
from hs h
join hs_makler t on t.zeile = h.zeile
left join hs_firma f on f.schluessel = h.schluessel
where not t.irgendwer;

-- Zusätzliche E-Mail-Adressen der vorhandenen Makler ins Unternehmen (ohne Unternehmen: an den Makler)
update fach.unternehmen u set
  weitere_kontakte = k.neu, version = u.version + 1, updated_at = now()
from (
  select u2.id, pg_temp.kontakte_vereinen(
      jsonb_build_array(coalesce(u2.weitere_kontakte, 'null'),
        jsonb_build_object('emails', (select coalesce(jsonb_agg(e), '[]') from hs h, unnest(h.weitere_emails) e
          where h.email_klein in (select lower(btrim(m.email)) from fach.makler m where m.unternehmen_id = u2.id and m.deleted_at is null)))),
      (select coalesce(jsonb_agg(jsonb_build_object('name', nullif(concat_ws(' ', m.vorname, m.name), ''), 'tel', m.tel, 'mobil', m.mobil,
         'festnetz', m.festnetz, 'email', m.email)), '[]') from fach.makler m where m.unternehmen_id = u2.id and m.deleted_at is null)) as neu
  from fach.unternehmen u2
  where u2.deleted_at is null
    and exists (select 1 from fach.makler m join hs h on h.email_klein = lower(btrim(m.email))
                where m.unternehmen_id = u2.id and m.deleted_at is null and cardinality(h.weitere_emails) > 0)
) k
where u.id = k.id and k.neu is distinct from u.weitere_kontakte;

update fach.makler m set
  weitere_kontakte = k.neu, version = m.version + 1, updated_at = now()
from (
  select m2.id, pg_temp.kontakte_vereinen(
      jsonb_build_array(coalesce(m2.weitere_kontakte, 'null'), jsonb_build_object('emails', to_jsonb(h.weitere_emails))),
      jsonb_build_array(jsonb_build_object('name', nullif(concat_ws(' ', m2.vorname, m2.name), ''), 'tel', m2.tel, 'mobil', m2.mobil,
        'festnetz', m2.festnetz, 'email', m2.email))) as neu
  from fach.makler m2
  join hs h on h.email_klein = lower(btrim(m2.email))
  where m2.deleted_at is null and m2.unternehmen_id is null and cardinality(h.weitere_emails) > 0
) k
where m.id = k.id and k.neu is distinct from m.weitere_kontakte;

drop table hubspot_roh, hs, hs_makler, hs_firma;
